    static const vector<AnalysisDimension> analysis_dims = {  
        {"chat", {"sentiment", "keywords", "problem_type"}},  // 文本分析
        {"transactions", {"total_amount", "user_id", "product_id"}}, // 交易数据
        {"browsing", {"page_views", "search_terms", "category"}}   // 浏览数据
    };

    static const vector<string> report_freq = {"daily", "weekly"};    // 报告频率
    static const string nlp_model_path = "model/nlp";                // NLP模型路径
    static sqlite3* db;                                      // 数据库实例

    Config() {
        if (!db) { 
            // 初始化数据库连接
        }
    }

    ~Config() {
        if (db) {
            // 关闭数据库连接
        }
    }
};

/**
 * @brief Data processing class for handling file operations and logging.
 */
class DataProcessor {
public:
    DataProcessor() {}
    ~DataProcessor() {}

    /**
     * @brief Prints log messages with current time.
     *
     * @param msg The message to log
     */
    void info(const string& msg) {
        cerr << "[" << getCurrentTime() << "] INFO: " << msg << endl;
    }
    /**
     * @brief Prints error messages with current time.
     *
     * @param msg The error message
     */
    void error(const string& msg) {
        cerr << "[" << getCurrentTime() << "] ERROR: " << msg << endl;
    }

private:
    static string getCurrentTime() {
        return ctime(&clock());
    }
};

/**
 * @brief Data reader class for loading files and managing threads.
 */
class DataReader {
public:
    DataReader(const Config& config)
        : config_(config) {}

    /**
     * @brief Loads all files in the data directory that match specified extensions.
     *
     * @return Vector of file paths
     */
    vector<string> loadFiles() const {
        vector<string> files;
        for (const auto& dir_entry : fs::directory_iterator(config_.data_dir)) {
            if (dir_entry.is_file()) {
                string file_path = dir_entry.path().string();
                // 检查文件扩展名是否在允许的列表中
                size_t last_dot = file_path.find_last_of('.');
                if (last_dot != string::npos) {
                    string ext = file_path.substr(last_dot + 1);
                    if (find(config_.file_exts.begin(), config_.file_exts.end(), ext) 
                        != config_.file_exts.end()) {
                        files.push_back(file_path);
                    }
                }
            }
        }
        return files;
    }

    /**
     * @brief Processes each file in parallel using threads.
     *
     * @param files List of files to process
     * @return Vector of processed dataframes
     */
    vector<DataFrame> processFiles(const vector<string>& files) const {
        vector<tuple<int, int, DataFrame>> futures;
        int thread_count = 2; // 可以根据需要调整线程数

        for (const string& file : files) {
            auto begin = make_unique<DataReader>(config_);
            auto future = new thread([this, file] {
                unique_ptr<DataReader> reader = make_unique<DataReader>(config_);
                DataFrame df;
                try {
                    // 具体实现文件读取逻辑
                    df = read_file(file);
                    info("成功读取文件：" + file);
                } catch (const exception& e) {
                    error("读取文件失败：" + file);
                    throw;
                }
            });
            futures.emplace_back(thread_get_id(), 0, future);
        }

        return {};
    }

private:
    unique_ptr<Config> config_;
};

/**
 * @brief Data cleaner class for preprocessing data.
 */
class DataCleaner : public DataProcessor {
public:
    DataCleaner(const Config& config)
        : config_(config) {}

    /**
     * @brief Cleans and preprocesses the input dataframe.
     *
     * @param input_df The input dataframe to clean
