                    numerical_cols.push_back(col);
                } else {
                    categorical_cols.push_back(col);
                }
            }

            // 填补数值缺失
            for (const string& col : numerical_cols) {
                double mean_val = 0;
                size_t n = 0;
                for (double val : input_df[col]) {
                    if (!isinf(val)) {
                        mean_val += val;
                        n++;
                    }
                }
                if (n > 0) {
                    input_df[col] = mean_val;
                } else {
                    // 可以选择填补为0或其他默认值
                    input_df[col] = 0;
                }
            }

            // 填补分类缺失
            for (const string& col : categorical_cols) {
                if (!input_df.empty && !input_df.dataTypes[col].is_string()) continue;

                vector<string> unique_values;
                map<string, int> value_counts;
                for (const string& val : input_df[col]) {
                    value_counts[val]++;
                }
                if (!value_counts.empty()) {
                    string most_common = *value_counts.begin()->second->first;
                    input_df[col] = most_common == "0" ? "unknown" : most_common;
                } else {
                    input_df[col] = "unknown";
                }
            }

            // 时间格式统一
            vector<string> time_cols;
            for (const string& col : input_df.columns()) {
                if (col.find("time") != string::npos) {
                    time_cols.push_back(col);
                }
            }
            for (const string& col : time_cols) {
                if (input_df.dataTypes[col] == "datetime") {
                    // 转换为标准格式
                } else if (input_df.dataTypes[col] == "string") {
                    // 使用C++日期时间库解析
                    for (string& val : input_df[col]) {
                        // 具体实现日期解析逻辑
                    }
                }
            }

            // 文本标准化
            vector<string> text_cols;
            for (const string& col : input_df.columns()) {
                if (col.find("text") != string::npos) {
                    text_cols.push_back(col);
                }
            }
            for (const string& col : text_cols) {
                for (string& val : input_df[col]) {
                    // 去掉特殊符号
                    val = regex_replace(val, "[^a-zA-Z0-9]", "");
                    // 分词处理（可以使用预定义的分词器）
                    vector<string> words;
                    istringstream iss(val);
                    while (iss >> word) {
                        words.push_back(word);
                    }
                    val = join(words, " ");
                }
            }

        } else {
            result = input_df;
        }

        return result;
    }
};

