    }

};

class DataProcessorImpl {
private:
    vector<thread> threads;
    mutex mtx;
    condition_variable cond;

public:
    DataProcessorImpl() {}

    template<typename T>
    shared_ptr<T> processFile(const string& path) {
        lock_guard lock(mtx);
        if (threads.empty()) {
            threads.push_back(new thread([this, path], 
                [this](auto future) {
                    shared_ptr<T> data = this->loadData(path);
                    future.set_result(data);
                }));
            cond.notify_one();
        } else {
            // 多重起始に対応する方法です
            // 例：スレッドを並行的に起動し、順序を管理します
        }
    }

    template<typename T>
    shared_ptr<T> loadData(const string& path) {
        return DataProcessor::loadFile(path);
    }

};

