    // 各スレッドのデータ処理を並行的に実行します
    vector<shared_ptr<thread>> threads;
    for (const auto& path : filesystem::list_directory(data_dir)) {
        if (path.path().extension() == ".csv" || path.path().extension() == ".json") {
            threads.push_back(new thread([processor, path], 
                [processor](auto& future) {
                    shared_ptr<vector<string>> data = processor.loadData(path);
                    if (data) {
                        future.set_result(data);
                    } else {
                        future.set_exception(current_exception());
                    }
                }));
        }
    }

    // 各スレッドを.join()して待機します
    for (auto& thread : threads) {
        thread.join();
    }

    // データ分析とレポート生成の部分を省略します

    return 0;
}
