         * 重複した行は最初の1行のみを保留し、
         * 空白または不要な文字を削除して文本を整理します。
         */
        vector<string> uniqueTexts;
        map<string, string> textMap;

        for (const auto& text : *texts) {
            if (!text.empty()) {
                // 重複削除
                if (textMap.find(text) == textMap.end()) {
                    textMap[text] = text;
                }
            }
