    // 取引データの前処理
    shared_ptr<vector<double>> cleanTransactionData(const shared_ptr<vector<double>>& amounts) {
        /* 取引レコード内で重复した商品やユーザーを削除し、欠損値を補正する。
         * 数量が不定形（nanなど）である場合、ゼロに置き換える。
         */
        vector<double> uniqueAmounts;
        map<long long, double> amountMap;

        for (double amount : *amounts) {
            if (!isinf(amount)) {
                // 欠損値補充
                double cleanedAmount = isfinite(amount) ? round(amount) : 0.0;
                if (amountMap.find(static_cast<long long>(cleanedAmount)) == amountMap.end()) {
                    amountMap[static_cast<long long>(cleanedAmount)] = cleanedAmount;
                }
            }
        }

        vector<double> cleanedAmounts;
        for (auto& pair : amountMap) {
            cleanedAmounts.push_back(pair.second);
        }

        return make_shared<vector<double>>(cleanedAmounts);
    }

    // 主な静的メンバ関数
