        unique_ptr<fstream> file;
        file.open(path, ios::in);
        if (!file) {
            return nullptr;
        }

        vector<string> data;
        string line;
        while (getline(file, line)) {
            data.push_back(line);
        }
        return make_shared<vector<string>>(data);
    }

