        lock_guard lock(mtx);
        if (threads.empty()) {
            threads.push_back(new thread([this, path], 
                [this](auto future) {
                    shared_ptr<T> data = this->loadData(path);
                    future.set_result(data);
                }));
            cond.notify_one();
        } else {
