        }
    }

    template<typename T>
    shared_ptr<T> loadData(const string& path) {
        /* データファイルを読み込む。
         * DataProcessor::loadFile を呼び、データを返却します。
         */
        return DataProcessor::loadFile(path);
    }
};

// メイン処理
int main() {
    /* メインプロセッサが開始しました */
    cout << "メインプロセッサが開始しました" << endl;

    /* データディレクトリとデータベース接続情報をセットします */
    const string data_dir = "data";
    const string db_url = "postgresql://user:password@localhost/database";

    DataProcessorImpl processor;

    /* 各スレッドのデータ処理を並行的に実行します */
