class Database {
private:
    string type;  // Type of database (e.g., "PostgreSQL")
    string host;  // Database server hostname
    string dbname; // Database name
    string user;  // Database username
    string pass;  // Database password

public:
    Database(string type, string host, string dbname, string user, 
             string pass) : type(type), host(host), dbname(dbname), 
                            user(user), pass(pass) {}

    // Connect to the database using the provided credentials
    virtual ~Database() = default;

    // Example method for inserting data into the database
