    }

    // Method to read all CSV/JSON files from the specified directory
    void readFiles() {
        filesystem dir(config_path);  // Create a filesystem object for the config directory

        // Iterate through all entries in the directory
        for (auto& entry : dir.iterative_status()) {
            if (entry.is_file()) {  // Check if the entry is a file
                string ext = entry.extension();  // Get the file extension

                // Check if the file is either a CSV or JSON file
                if ((ext == "csv") || (ext == "json")) {
                    files.push_back(entry.path().string());  // Add file path to the vector
                }
            }
        }

        cout << "Found " << files.size() << " files to process" << endl;  // Output log info
    }

    // Method to process a single file in parallel using threads
    void processFile(int index, mutex& mx) {
        try {
            string file_path = files[index];  // Get the current file path

            // Use a unique mutex for this file operation to prevent data races
            lock_guard<mutex> lg(mx);

            // Open the file and read its contents
            ifstream ifs(file_path);
            vector<string> lines;

            while (getline(ifs, line)) {  // Read each line of the file
                lines.push_back(line);  // Store the line in a temporary vector
            }

            if (!lines.empty()) {  // If there are lines to process
                cout << "Processing: " << file_path << endl;  // Log processing status

                // TODO: Implement deduplication and other preprocessing logic here
                // For example, you might want to:
