                // - Handle missing values in numeric columns using mean/median/mode
                // - Standardize time formats from strings to UTC datetime objects
                // - Clean and preprocess text data (e.g., remove special characters, word segmentation)

                // Insert processed data into the database
                db->insertData("processed_logs", lines);  // Replace "processed_logs" with your table name
            }
        } catch (const exception& e) {  // Catch any exceptions during file processing
            cerr << "Error processing file '" << file_path << "': " << e.what() << endl;
        }
    }

    // Method to start parallel processing of all files
    void startProcessing() {
        mutex mx;  // Mutex to control access to shared data

        vector<thread> threads;  // Vector to store thread objects

        for (int i = 0; i < files.size(); ++i) {  // Iterate over each file
            threads.push_back(new thread(&DataProcessor::processFile, this, i, mx));  // Create a new thread
        }

        // Wait until all threads have completed their tasks
        while (!all_of(begin(threads), end(threads), [](const thread& t){ return t.joinable(); })) {
            this_thread::sleep_for(chrono::milliseconds(1));  // Sleep briefly to avoid high CPU usage
        }
    }

    ~DataProcessor() {  // Destructor to clean up database connection and other resources
        delete db;  // Ensure database pointer is properly deleted
    }
};

int main() {
    try {  // Main function to run the data processing pipeline
        DataProcessor dp("config");  // Initialize DataProcessor with configuration directory

        // Read all files from the specified directory
        dp.readFiles();

        // Start parallel processing of all discovered files
        dp.startProcessing();

        return 0;  // Return exit code (0 for success)
    } catch (const exception& e) {  // Catch any exceptions during initialization
        cerr << "Error initializing data processor: " << e.what() << endl;
        return -1;  // Return non-zero exit code to indicate failure
    }
}
```

