3. **`startProcessing()`**:
   ```cpp
   void DataProcessor::startProcessing() {
       mutex mx;  // Mutex to control access to shared data

       vector<thread> threads;  // Vector to store thread objects

       for (int i = 0; i < files.size(); ++i) {  // Iterate over each file
           threads.push_back(new thread(&DataProcessor::processFile, this, i, mx));  // Create a new thread
       }

       // Wait until all threads have completed their tasks
       while (!all_of(begin(threads), end(threads), [](const thread& t){ return t.joinable(); })) {
           this_thread::sleep_for(chrono::milliseconds(1));  // Sleep briefly to avoid high CPU usage
       }
   ```
